from collections import Counter

def top_k(nums, k):
    buckets = [[]] * (len(nums) + 1)
    for v, f in Counter(nums).items():
        buckets[f].append(v)
    out = []
    for f in range(len(buckets) - 1, 0, -1):
        for v in buckets[f]:
            out.append(v)
            if len(out) == k:
                return out
    return out
